export function FeedCard({
  item,
  locale,
  onDelete,
  onEdit,
  onSaveChange,
  articleAccess = 'owner',
}: {
  item: FeedItem
  locale: string
  onDelete?: (item: FeedItem) => void
  onEdit?: (item: FeedItem) => void
  onSaveChange?: (item: FeedItem, isSaved: boolean) => void
  articleAccess?: 'community' | 'owner'
}) {
  const isArabic = locale === 'ar'
  const copy = copyByLocale[isArabic ? 'ar' : 'en']
  const toast = useToast()
  const router = useRouter()
  const { user } = useUserProfile()
  const [openingInsight, setOpeningInsight] = useState<string | null>(null)
  const [isTracked, setIsTracked] = useState(item.is_tracked === true)
  const [isUpdatingTrack, setIsUpdatingTrack] = useState(false)
  const [isBodyExpanded, setIsBodyExpanded] = useState(false)
  const [isBodyOverflowing, setIsBodyOverflowing] = useState(false)
  const bodyContentRef = useRef<HTMLDivElement>(null)
  const cardRef = useRef<HTMLElement>(null)
  const isCollapsingBodyRef = useRef(false)
  const date = formatPostDate(item.published_at ?? item.created_at, locale)
  const isArticle = item.content_type === 'article'
  const isPostTitleArabic = isFirstWordArabic(item.title ?? '')
  const postBodyText = stripHtml(item.body ?? '')
  const isPostBodyArabic = isFirstWordArabic(postBodyText)
  const isRichPostBody = /<\/?[a-z][^>]*>/i.test(item.body ?? '')
  const imageMedia = item.media.filter((media) => media.media_type === 'image' && media.url)
  const articleCover = isArticle ? imageMedia[0] : undefined
  const videoMedia = item.media.find((media) => media.media_type === 'video')
  const attachments = item.media.filter(
    (media) => media.media_type === 'attachment' && media.url,
  )
  const hasPostMedia = Boolean(videoMedia) || imageMedia.length > 0
  const hasRichContent =
    isArticle || hasPostMedia || attachments.length > 0 || item.related_insights.length > 0
  const showEngagementActions = articleAccess === 'community' && Boolean(item.insighter)
  const showShareAction = Boolean(item.insighter)
  const isMediaLast =
    attachments.length === 0 && item.related_insights.length === 0 && !showShareAction
  const statusTone =
    item.status === 'published'
      ? 'bg-[#EAF8F1] text-[#168A55]'
      : item.status === 'failed'
        ? 'bg-[#FFF0EE] text-[#B53B32]'
        : 'bg-[#FFF5E5] text-[#A96710]'
  const insighter = item.insighter
  const isPublishedAsCompany = item.author_profile_type === 'company' && Boolean(insighter?.company)
  const publisherName = isPublishedAsCompany
    ? insighter?.company?.legal_name || insighter?.company?.name || insighter?.name || ''
    : insighter?.name || ''
  const publisherAvatar = isPublishedAsCompany
    ? insighter?.company?.logo
    : insighter?.profile_photo_url
  const publisherInitials = publisherName
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase()
  const publisherHref = isPublishedAsCompany
    ? `/${locale}/profile/${insighter?.company?.uuid}`
    : `/${locale}/profile/${insighter?.uuid}?entity=insighter`

  // Community-feed engagement actions (Meet / Request Service / Share) are only
  // meaningful when viewing someone else's published post in the public feed.
  // `showEngagementActions` is derived above (near the media flags).
  const isOwnPost = Boolean(user?.uuid && insighter && user.uuid === insighter.uuid)
  const canMeet = insighter?.has_meet_service === true
  const canRequestService = insighter?.has_request_service === true
  const meetHref = insighter
    ? `/${locale}/profile/${insighter.uuid}?entity=insighter&tab=meet`
    : ''
  const requestServiceHref = insighter
    ? `/${locale}/project/wizard/project-type?${new URLSearchParams({
        fresh: '1',
        [specifiedInsighterQueryParam]: insighter.uuid,
        [specifiedInsighterRoleQueryParam]: 'insighter',
        [specifiedInsighterProfileUuidQueryParam]: insighter.uuid,
      }).toString()}`
    : ''
  const shareUrl = isArticle
    ? `${publicBaseUrl}/${locale}/article/${item.slug ?? item.uuid}`
    : `${publicBaseUrl}/${locale}/post/${item.slug ?? item.uuid}`
  const shareTitle = item.title?.trim() || stripHtml(item.body ?? '').slice(0, 120) || insighter?.name || ''
  const tagHashtags = item.tags
    .map((tag) => toHashtagToken(tag.name))
    .filter(Boolean)
    .map((tagName) => `#${tagName}`)
  const tagHashtagsKey = tagHashtags.join(' ')
  const handleHashtagClick = (hashtag: string) => {
    router.push(`/${locale}?keyword=${encodeURIComponent(hashtag.replace(/_/g, ' '))}`)
  }

  useEffect(() => {
    setIsTracked(item.is_tracked === true)
  }, [item.is_tracked, item.uuid])

  useEffect(() => {
    setIsBodyExpanded(false)
  }, [item.body, item.uuid, tagHashtagsKey])

  useEffect(() => {
    const bodyContent = bodyContentRef.current
    if (!bodyContent) {
      setIsBodyOverflowing(false)
      return
    }

    const measureOverflow = () => {
      // While expanded the clamp is off, so the element can no longer tell us
      // whether the collapsed state would crop. Keep the last measurement.
      if (isBodyExpanded) return
      setIsBodyOverflowing(bodyContent.scrollHeight > bodyContent.clientHeight + 1)
    }

    measureOverflow()
    const resizeObserver = new ResizeObserver(measureOverflow)
    resizeObserver.observe(bodyContent)

    return () => resizeObserver.disconnect()
  }, [item.body, isBodyExpanded, tagHashtagsKey])

  const toggleBodyExpanded = () => {
    isCollapsingBodyRef.current = isBodyExpanded
    setIsBodyExpanded((expanded) => !expanded)
  }

  // Collapsing a long post removes content above the viewport, which would
  // otherwise leave the reader parked on the next post.
  useBrowserLayoutEffect(() => {
    if (isBodyExpanded || !isCollapsingBodyRef.current) return
    isCollapsingBodyRef.current = false
    cardRef.current?.scrollIntoView({ block: 'nearest', behavior: 'instant' })
  }, [isBodyExpanded])

  const updateTracking = async () => {
    if (isUpdatingTrack || isOwnPost) return

    if (!user) {
      const returnUrl = encodeURIComponent(window.location.href)
      window.location.assign(`${dashboardUrl}/auth/login?returnUrl=${returnUrl}`)
      return
    }

    setIsUpdatingTrack(true)
    try {
      const result = await setCommunityFeedItemTracked(item.uuid, !isTracked, locale)
      setIsTracked(result.is_tracked)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : copy.trackFailed)
    } finally {
      setIsUpdatingTrack(false)
    }
  }

  return (
    <article
      ref={cardRef}
      className="relative min-w-0 max-w-full scroll-mt-20 overflow-hidden rounded-lg border border-[#D9E3EF] bg-white px-5 py-5 sm:px-6 md:scroll-mt-24"
    >
      <div className="flex min-h-9 items-start justify-between gap-3 sm:gap-4">
        <div className={`min-w-0 flex-1 ${articleAccess === 'community' ? 'pe-[76px] sm:pe-0' : ''}`}>
          {insighter && (
            <div className="flex min-w-0 items-center gap-3">
              <div className="h-10 w-10 shrink-0">
                <div className="h-10 w-10 overflow-hidden rounded-full bg-[#E7F0FE]">
                {publisherAvatar ? (
                  <img
                    src={publisherAvatar}
                    alt={publisherName}
                    className={`h-full w-full object-cover ${isPublishedAsCompany ? '' : 'object-top'}`}
                  />
                ) : (
                  <div className="flex h-full w-full items-center justify-center text-[13px] font-bold text-[#2378E8]">
                    {publisherInitials || 'I'}
                  </div>
                )}
                </div>
              </div>
              <div className="min-w-0">
                <Link
                  href={publisherHref}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="block truncate text-[14px] font-semibold text-[#101724] transition-colors hover:text-[#2378E8] hover:underline focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-1"
                >
                  {publisherName}
                </Link>
                <div className="flex min-w-0 flex-col items-start gap-y-0.5 text-[12px] text-[#7A8BA4] sm:flex-row sm:items-center sm:gap-x-1.5 sm:text-[12.5px]">
                  {item.industry && (
                    <Link
                      href={`/${locale}/sub-industry/${item.industry.id}/${item.industry.slug}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="min-w-0 truncate font-medium text-[#2378E8] hover:underline"
                    >
                      {item.industry.name}
                    </Link>
                  )}
                  {date && item.industry && <span aria-hidden className="hidden shrink-0 sm:inline">·</span>}
                  {date && (
                    <time
                      dateTime={item.published_at ?? item.created_at ?? undefined}
                      className="shrink-0 whitespace-nowrap"
                    >
                      {date}
                    </time>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>

        {(onDelete || onEdit || articleAccess === 'community') && (
          <div className={`flex shrink-0 items-center gap-2 ${articleAccess === 'community' ? 'absolute end-4 top-4 sm:static' : ''}`}>
            {articleAccess === 'community' && (
              <Tooltip
                label={isOwnPost ? copy.ownPostTracking : isTracked ? copy.untrackTooltip : copy.trackTooltip}
                position="bottom"
                openDelay={300}
                withArrow
              >
                <span className="inline-flex">
                  <button
                    type="button"
                    onClick={() => void updateTracking()}
                    disabled={isUpdatingTrack || isOwnPost}
                    aria-pressed={isTracked}
                    aria-label={isUpdatingTrack ? copy.tracking : isTracked ? copy.untrack : copy.track}
                    className="inline-flex min-h-[28px] items-center justify-center gap-1 rounded-full border border-black bg-white px-2 py-0.5 text-[11px] font-semibold text-black transition-[background-color,border-color,color,box-shadow] hover:border-black hover:bg-white hover:text-black focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#64748B] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-55 sm:min-h-[34px] sm:gap-1.5 sm:px-3 sm:py-0 sm:text-[12px]"
                  >
                    {isUpdatingTrack ? (
                      <IconLoader2 aria-hidden className="h-4 w-4 animate-spin" stroke={2} />
                    ) : (
                      <span className={`flex h-4 w-4 shrink-0 items-center justify-center ${isTracked ? 'text-[#1D4ED8]' : 'text-[#A5B0BF]'} sm:h-5 sm:w-5`} aria-hidden>
                        <TrackSignalIcon animated={isTracked} />
                      </span>
                    )}
                    <span>{isTracked ? copy.untrack : copy.track}</span>
                  </button>
                </span>
              </Tooltip>
            )}

            {(onDelete || onEdit) && (
              <span className={`inline-block rounded-full px-2.5 py-1 text-[11px] font-semibold ${statusTone}`}>
                {item.status_label}
              </span>
            )}

            {(onDelete || onEdit) && (
              <Menu shadow="md" width={170} position={isArabic ? 'bottom-start' : 'bottom-end'}>
                <Menu.Target>
                  <button
                    type="button"
                    aria-label={copy.postActions}
                    className="flex h-9 w-9 items-center justify-center rounded-full text-[#8FA0B7] transition-colors hover:bg-[#F1F5FA] hover:text-[#253247] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8]"
                  >
                    <IconDots aria-hidden className="h-5 w-5" stroke={2.2} />
                  </button>
                </Menu.Target>
                <Menu.Dropdown>
                  {onEdit && (
                    <Menu.Item
                      leftSection={<IconEdit aria-hidden className="h-4 w-4" stroke={1.8} />}
                      onClick={() => onEdit(item)}
                    >
                      {isArticle ? copy.editArticle : copy.edit}
                    </Menu.Item>
                  )}
                  {onDelete && (
                    <Menu.Item
                      color="red"
                      leftSection={<IconTrash aria-hidden className="h-4 w-4" stroke={1.8} />}
                      onClick={() => onDelete(item)}
                    >
                      {copy.delete}
                    </Menu.Item>
                  )}
                </Menu.Dropdown>
              </Menu>
            )}
          </div>
        )}
      </div>

      {!isArticle && item.title && (
        <h2
          dir={isPostTitleArabic ? 'rtl' : 'ltr'}
          className={`mt-4 text-[17px] font-bold leading-6 tracking-[-0.02em] text-[#101724] ${isPostTitleArabic ? 'text-right' : 'text-left'}`}
        >
          {renderInteractiveFeedText(item.title, handleHashtagClick)}
        </h2>
      )}

      {!isArticle && (item.body || tagHashtags.length > 0) && (
        <div className={item.title ? 'mt-1.5' : 'mt-4'}>
          <div
            ref={bodyContentRef}
            dir={isPostBodyArabic ? 'rtl' : 'ltr'}
            className={`text-start text-[14px] leading-5 text-[#1C2433] [&_a]:font-medium [&_a]:text-[#2378E8] [&_a]:underline [&_a]:decoration-[#2378E8]/40 [&_a]:underline-offset-2 [&_a:hover]:text-[#155DB8] [&_p]:m-0 [&_p+p]:mt-2 [&_ul]:my-2 [&_ul]:list-disc [&_ul]:ps-5 [&_ol]:my-2 [&_ol]:list-decimal [&_ol]:ps-5 ${
              isRichPostBody ? '' : 'whitespace-pre-wrap'
            } ${
              isBodyExpanded ? 'line-clamp-none' : 'line-clamp-[10]'
            }`}
          >
            {item.body && (
              isRichPostBody ? (
                <div dangerouslySetInnerHTML={{ __html: sanitizeAndLinkifyRichPostHtml(item.body, locale) }} />
              ) : (
                renderInteractiveFeedText(item.body, handleHashtagClick)
              )
            )}

            {tagHashtags.length > 0 && (
              <div className={item.body ? 'mt-2' : ''}>
                {renderInteractiveFeedText(tagHashtagsKey, handleHashtagClick)}
              </div>
            )}
          </div>

          {isBodyOverflowing && (
            <div dir={isPostBodyArabic ? 'rtl' : 'ltr'} className="mt-1.5 flex">
              <button
                type="button"
                aria-expanded={isBodyExpanded}
                onClick={toggleBodyExpanded}
                className="text-[12px] font-semibold text-[#2378E8] transition-colors hover:text-[#155DB8] hover:underline focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
              >
                {isBodyExpanded ? copy.readLess : copy.readMore}
              </button>
            </div>
          )}
        </div>
      )}

      {isArticle && (
        <ArticlePreview
          item={item}
          cover={articleCover}
          locale={locale}
          isPublic={articleAccess === 'community'}
          flushBottom={isMediaLast}
        />
      )}

      {!isArticle && videoMedia && (
        <VideoPlayer
          media={videoMedia}
          title={item.title ?? item.body ?? 'Video'}
          playLabel={copy.playVideo}
          flushBottom={isMediaLast}
        />
      )}
      {!isArticle && imageMedia.length > 0 && <ImageGallery media={imageMedia} imageAlt={copy.imageAlt} locale={locale} flushBottom={isMediaLast} />}

      {attachments.length > 0 && (
        <div className="mt-5 space-y-2">
          {attachments.map((attachment) => (
            <a
              key={attachment.id}
              href={attachment.url ?? '#'}
              target="_blank"
              rel="noreferrer"
              className="flex items-center gap-3 rounded-md border border-[#DDE6F1] bg-[#F8FAFD] px-4 py-3 text-[13px] font-medium text-[#2378E8] transition-colors hover:bg-[#F1F6FD]"
            >
              <IconFileDescription aria-hidden className="h-5 w-5" stroke={1.7} />
              <span className="min-w-0 flex-1 truncate">{attachment.name ?? copy.attachment}</span>
            </a>
          ))}
        </div>
      )}

      {item.related_insights.length > 0 && (
        <div className={`-mx-5 ${hasPostMedia ? 'mt-0' : 'mt-5'} divide-y divide-[#E7EDF5] overflow-hidden border-t border-[#E7EDF5] sm:-mx-6 ${
          showShareAction ? 'border-b' : '-mb-5 rounded-b-lg sm:-mb-6'
        }`}>
          {item.related_insights.map((insight) => {
            const insightKey = `${insight.type}-${insight.slug}`
            const insightPrice = getInsightPrice(insight.price, locale === 'ar' ? 'مجاني' : 'Free')

            return (
            <div
              key={`${insight.type}-${insight.slug}`}
              className="group flex flex-col overflow-hidden bg-white transition-colors duration-300 hover:bg-[#F8FAFD] sm:flex-row"
            >
              <Link
                href={`/${locale}/knowledge/${insight.type}/${insight.slug}`}
                target="_blank"
                rel="noreferrer"
                aria-label={`${copy.viewInsight}: ${insight.title}`}
                className="flex min-h-[118px] w-full min-w-0 flex-col bg-[#071426] bg-[url('/images/test2.png')] bg-cover bg-center px-4 py-2.5 text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[#67B5F6] sm:min-h-[155px] sm:w-[36%] sm:max-w-[280px] sm:flex-none sm:py-4"
              >
                <div>
                  <div className="flex items-center gap-2">
                    <KnowledgeTypeIcon type={insight.type} size={16} />
                    <span className="rounded-full bg-[#0B315D]/80 px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-[0.05em] text-[#67B5F6] backdrop-blur-sm">
                      {insight.type}
                    </span>
                  </div>
                  <h3
                    dir="auto"
                    className="mt-2.5 line-clamp-2 text-start text-[15px] font-semibold leading-6 text-white transition-colors group-hover:text-[#A8D5FF] sm:mt-4 sm:line-clamp-3 sm:text-[16px]"
                  >
                    {insight.title}
                  </h3>
                </div>
              </Link>

              <div className="flex min-w-0 flex-1 flex-col bg-white px-4 py-4 sm:min-h-[155px] sm:px-5 sm:py-4">
                <div className="flex min-w-0 flex-1 flex-col sm:min-h-[123px]">
                  {insight.description && (
                    <p
                      dir="auto"
                      className="line-clamp-3 text-[13px] leading-[1.2rem] text-[#667894] max-sm:hidden sm:text-[14px]"
                    >
                      {stripHtml(insight.description)}
                    </p>
                  )}
                  <div className="mt-auto flex items-center justify-between gap-4 pt-0 sm:pt-4" dir={locale === 'ar' ? 'rtl' : 'ltr'}>
                    {insightPrice ? (
                      <Badge color={insightPrice.isFree ? 'green' : 'yellow'} variant="light" className="shrink-0 font-semibold">
                        <span dir={insightPrice.isFree ? 'auto' : 'ltr'} lang={insightPrice.isFree ? undefined : 'en'}>{insightPrice.label}</span>
                      </Badge>
                    ) : <span />}
                  <Link
                    href={`/${locale}/knowledge/${insight.type}/${insight.slug}`}
                    target="_blank"
                    rel="noreferrer"
                    aria-busy={openingInsight === insightKey}
                    onClick={() => {
                      setOpeningInsight(insightKey)
                      window.setTimeout(() => {
                        setOpeningInsight((current) => (current === insightKey ? null : current))
                      }, 1800)
                    }}
                    className="inline-flex min-h-7 min-w-16 items-center justify-center rounded-full border border-[#2378E8] px-2 py-0 text-center text-[13px] font-medium text-[#2378E8] transition-colors hover:bg-[#F2F7FF] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
                  >
                    {openingInsight === insightKey ? (
                      <>
                        <IconLoader2 aria-hidden className="me-1.5 h-4 w-4 animate-spin" stroke={2} />
                        <span aria-live="polite">{copy.openingInsight}</span>
                      </>
                    ) : (
                      copy.viewInsight
                    )}
                  </Link>
                  </div>
                </div>
              </div>
            </div>
            )
          })}
        </div>
      )}

      {showShareAction && insighter && (
        <div
          className={`-mx-5 flex min-w-0 items-center justify-around border-t border-[#E7EDF5] px-5 pt-2 sm:-mx-6 sm:px-6 ${hasRichContent ? 'mt-0' : 'mt-4'}`}
          dir={isArabic ? 'rtl' : 'ltr'}
        >
          {showEngagementActions && !isOwnPost && canMeet && (
            <Link
              href={meetHref}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex min-w-0 flex-1 items-center justify-center gap-1 rounded-md px-1 py-2.5 text-[12px] font-medium text-[#5A6B85] transition-colors hover:bg-[#F5F8FC] hover:text-[#101724] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] sm:gap-2 sm:px-2 sm:text-[14px]"
            >
              <IconCalendarUser aria-hidden className="h-4 w-4 shrink-0 text-[#2378E8] sm:h-[18px] sm:w-[18px]" stroke={1.8} />
              <span>{copy.meet}</span>
            </Link>
          )}

          {showEngagementActions && !isOwnPost && canRequestService && (
            <Link
              href={requestServiceHref}
              className="inline-flex min-w-0 flex-1 items-center justify-center gap-1 rounded-md px-1 py-2.5 text-[12px] font-medium text-[#5A6B85] transition-colors hover:bg-[#F5F8FC] hover:text-[#101724] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] sm:gap-2 sm:px-2 sm:text-[14px]"
            >
              <IconBriefcase aria-hidden className="h-4 w-4 shrink-0 text-[#16A34A] sm:h-[18px] sm:w-[18px]" stroke={1.8} />
              <span>{copy.requestService}</span>
            </Link>
          )}

          {showEngagementActions && !isOwnPost && (
            <FeedSaveButton
              uuid={item.uuid}
              identifier={item.slug ?? item.uuid}
              contentType={item.content_type}
              initialIsSaved={item.is_saved}
              locale={locale}
              layout="action"
              onChange={(isSaved) => onSaveChange?.(item, isSaved)}
            />
          )}

          <FeedShare
            shareUrl={shareUrl}
            shareTitle={shareTitle}
            authorName={insighter.name}
            authorPhotoUrl={insighter.profile_photo_url}
            locale={locale}
            shareKind={isArticle ? 'white-paper' : 'post'}
          />
        </div>
      )}
    </article>
  )
}

export default function MyFeedsTimeline({ locale }: MyFeedsTimelineProps) {
  const isArabic = locale === 'ar'
  const copy = copyByLocale[isArabic ? 'ar' : 'en']
  const toast = useToast()
  const router = useRouter()
  const { user, roles, isAuthResolved } = useUserProfile()
  const [items, setItems] = useState<FeedItem[]>([])
  const [page, setPage] = useState(1)
  const [lastPage, setLastPage] = useState(1)
  const [total, setTotal] = useState(0)
  const [isLoading, setIsLoading] = useState(true)
  const [isLoadingMore, setIsLoadingMore] = useState(false)
  const [loadError, setLoadError] = useState(false)
  const [deleteCandidate, setDeleteCandidate] = useState<FeedItem | null>(null)
  const [editCandidate, setEditCandidate] = useState<FeedItem | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const canViewOwnFeeds = useMemo(
    () =>
      roles.some((role) => ['insighter', 'company', 'company-insighter'].includes(role)),
    [roles],
  )

  const loadFirstPage = useCallback(
    async (signal?: AbortSignal) => {
      setIsLoading(true)
      setLoadError(false)
      try {
        const result = await getMyFeeds(1, locale, signal)
        setItems(result.data)
        setPage(result.meta.current_page)
        setLastPage(result.meta.last_page)
        setTotal(result.meta.total)
      } catch (error) {
        if (error instanceof DOMException && error.name === 'AbortError') return
        setLoadError(true)
      } finally {
        if (!signal?.aborted) setIsLoading(false)
      }
    },
    [locale],
  )

  useEffect(() => {
    if (!isAuthResolved || !user || !canViewOwnFeeds) {
      if (isAuthResolved) setIsLoading(false)
      return
    }

    const controller = new AbortController()
    void loadFirstPage(controller.signal)
    return () => controller.abort()
  }, [canViewOwnFeeds, isAuthResolved, loadFirstPage, user])

  useEffect(() => {
    const refresh = () => void loadFirstPage()
    window.addEventListener('feed:published', refresh)
    return () => window.removeEventListener('feed:published', refresh)
  }, [loadFirstPage])

  const loadMore = async () => {
    if (isLoadingMore || page >= lastPage) return

    setIsLoadingMore(true)
    try {
      const result = await getMyFeeds(page + 1, locale)
      setItems((previous) => {
        const existing = new Set(previous.map((item) => item.uuid))
        return [...previous, ...result.data.filter((item) => !existing.has(item.uuid))]
      })
      setPage(result.meta.current_page)
      setLastPage(result.meta.last_page)
      setTotal(result.meta.total)
    } catch {
      toast.error(copy.loadError)
    } finally {
      setIsLoadingMore(false)
    }
  }

  const editItem = async (item: FeedItem) => {
    if (item.content_type === 'article') {
      router.push(`/${locale}/article/write?edit=${encodeURIComponent(item.uuid)}`)
      return
    }

    try {
      setEditCandidate(await getFeedItem(item.uuid, locale))
    } catch (error) {
      toast.error(error instanceof Error ? error.message : copy.editFailed)
    }
  }

  const editMode: PostModalMode = editCandidate?.media_type === 'video'
    ? 'video'
    : editCandidate?.media_type === 'image'
      ? 'image'
      : 'post'

  const confirmDelete = async () => {
    if (!deleteCandidate || isDeleting) return

    setIsDeleting(true)
    try {
      await deleteFeedItem(deleteCandidate.uuid, locale)
      setItems((previous) => previous.filter((item) => item.uuid !== deleteCandidate.uuid))
      setTotal((previous) => Math.max(0, previous - 1))
      setDeleteCandidate(null)
      toast.success(copy.deleted)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : copy.deleteFailed)
    } finally {
      setIsDeleting(false)
    }
  }

  if (!isAuthResolved || isLoading) {
    return (
      <section aria-label={copy.loading}>
        <FeedSkeleton />
      </section>
    )
  }

  if (loadError) {
    return (
      <section className="rounded-lg border border-[#DCE4EF] bg-white px-6 py-12 text-center">
        <h1 className="text-[18px] font-bold text-[#101724]">{copy.loadError}</h1>
        <button
          type="button"
          onClick={() => void loadFirstPage()}
          className="mt-4 min-h-10 rounded-md bg-[#2378E8] px-5 text-[13px] font-semibold text-white transition-colors hover:bg-[#1B64C5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
        >
          {copy.tryAgain}
        </button>
      </section>
    )
  }

  return (
    <section aria-labelledby="my-feeds-title">
      <div className="mb-3 flex items-end justify-between gap-4 px-1">
        <h1 id="my-feeds-title" className="text-[20px] font-semibold tracking-[-0.02em] text-[#101724]">
          {copy.title}
        </h1>
        <span className="text-[12px] text-[#7A8BA4]">{copy.count(total)}</span>
      </div>

      {items.length === 0 ? (
        <div className="rounded-lg border border-[#DCE4EF] bg-white px-6 py-14 text-center">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-[#EDF4FD] text-[#2378E8]">
            <IconPhoto aria-hidden className="h-5 w-5" stroke={1.7} />
          </div>
          <h2 className="mt-4 text-[18px] font-bold text-[#101724]">{copy.emptyTitle}</h2>
          <p className="mx-auto mt-2 max-w-sm text-[13px] leading-6 text-[#64748B]">
            {copy.emptyDescription}
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {items.map((item, index) => {
            // Right-column widgets are hidden below xl, so weave them between
            // posts (LinkedIn-style) on mobile/tablet. Positions clamp to the
            // last post so short feeds still surface them.
            const upgradeIndex = Math.min(1, items.length - 1)
            const documentsIndex = Math.min(3, items.length - 1)

            return (
              <Fragment key={item.uuid}>
                <FeedCard item={item} locale={locale} onEdit={(feedItem) => void editItem(feedItem)} onDelete={setDeleteCandidate} />
                {index === upgradeIndex && (
                  <RoleUpgradeCard locale={locale} className="xl:hidden" />
                )}
                {index === documentsIndex && (
                  <TopDocumentsCard locale={locale} className="xl:hidden" />
                )}
              </Fragment>
            )
          })}
        </div>
      )}

      {page < lastPage && (
        <button
          type="button"
          onClick={() => void loadMore()}
          disabled={isLoadingMore}
          className="mt-4 flex min-h-11 w-full items-center justify-center rounded-lg border border-[#C8D8EB] bg-white px-4 text-[13px] font-semibold text-[#2378E8] transition-colors hover:bg-[#F5F9FE] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] disabled:cursor-wait disabled:opacity-60"
        >
          {isLoadingMore ? copy.loadingMore : copy.loadMore}
        </button>
      )}

      <Modal
        opened={deleteCandidate !== null}
        onClose={() => {
          if (!isDeleting) setDeleteCandidate(null)
        }}
        centered
        size="sm"
        radius={8}
        title={copy.deleteTitle}
        closeOnClickOutside={!isDeleting}
        closeOnEscape={!isDeleting}
        styles={{
          title: { color: '#101724', fontWeight: 700, fontSize: 18 },
          content: { border: '1px solid #DCE4EF', boxShadow: 'none' },
        }}
      >
        <p className="text-[13px] leading-6 text-[#64748B]">{copy.deleteDescription}</p>
        <div className="mt-6 flex justify-end gap-2.5">
          <button
            type="button"
            onClick={() => setDeleteCandidate(null)}
            disabled={isDeleting}
            className="min-h-10 rounded-md border border-[#CAD6E5] px-4 text-[13px] font-semibold text-[#536680] transition-colors hover:bg-[#F5F8FC] disabled:opacity-50"
          >
            {copy.cancel}
          </button>
          <button
            type="button"
            onClick={() => void confirmDelete()}
            disabled={isDeleting}
            className="min-h-10 rounded-md bg-[#D6453D] px-4 text-[13px] font-semibold text-white transition-colors hover:bg-[#B93831] disabled:cursor-wait disabled:opacity-60"
          >
            {isDeleting ? copy.deleting : copy.delete}
          </button>
        </div>
      </Modal>

      <PostModal
        locale={locale}
        mode={editMode}
        opened={editCandidate !== null}
        draft={editCandidate}
        onClose={() => setEditCandidate(null)}
        onDraftSaved={() => {
          setEditCandidate(null)
          void loadFirstPage()
        }}
        onDraftDiscarded={() => {
          setEditCandidate(null)
          void loadFirstPage()
        }}
        onPublished={() => {
          setEditCandidate(null)
          void loadFirstPage()
          window.dispatchEvent(new Event('feed:published'))
        }}
      />
    </section>
  )
}
